insert into public.questions(id,title,body,topic,city,status,is_demo,created_at) values(md5('bb-p4-volunteer-0')::uuid,'Сообщества волонтёров: помощь семьям рядом','В Birge Bol появился раздел «Волонтёры». Здесь можно обсудить сопровождение на мероприятия, помощь с организацией встреч и образовательные инициативы. В первом сообщении достаточно города, удобного формата и общего запроса — без документов ребёнка.','Новости','Алматы','answered',true,now()-make_interval(mins=>0)) on conflict(id) do nothing;
