insert into public.questions(id,title,body,topic,city,status,is_demo,created_at) values(md5('bb-p4-volunteer-2')::uuid,'Хочу помочь семье: с чего начать волонтёру?','Расскажите о городе, доступном времени и том, чем готовы помочь: сопровождение, подготовка материалов или организация событий. Не обещайте медицинскую помощь без соответствующей квалификации. Знакомство и границы участия обсуждаются с родителем.','Волонтёры','Алматы','answered',true,now()-make_interval(mins=>2)) on conflict(id) do nothing;
