alter table public.questions drop constraint questions_topic_check;alter table public.questions add constraint questions_topic_check check(topic in('Новости','Мероприятия','Поведение','Обучение','Сон и быт','Семья','Речь','Занятия','ПМПК','Поддержка','Волонтёры'));
do $$declare c record;begin for c in select conname from pg_constraint where conrelid='public.community_preferences'::regclass and contype='c' and pg_get_constraintdef(oid) like '%topics%' loop execute format('alter table public.community_preferences drop constraint %I',c.conname);end loop;end$$;
alter table public.community_preferences add constraint community_topics_allowed check(topics<@array['Новости','Мероприятия','Поведение','Обучение','Сон и быт','Семья','Речь','Занятия','ПМПК','Поддержка','Волонтёры']::text[]);
with ranked as(select id,row_number()over(order by case when title ilike '%оплат%' then 0 else 1 end,created_at desc) rn from public.notifications where parent_id='20000000-0000-4000-8000-000000000001' and not read) update public.notifications n set read=true from ranked r where n.id=r.id and r.rn>3;
